{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Codeine, the closest morphinan analogue sharing the 4,5-epoxy-N-methylmorphinan scaffold, has 80.5% oral bioavailability in healthy subjects, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ethinylestradiol, a phenolic steroid with extensive first-pass glucuronidation/sulfation, still shows absolute oral bioavailability of 62 ± 10%, supporting that phenolic first-pass liability does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Meperidine, a tertiary-amine opioid analgesic, has absolute oral bioavailability around 0.56–0.60, supporting high F for a basic amine-containing opioid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Melperone, a basic amine drug, shows absolute oral bioavailability of 67 ± 28%, supporting high F for basic amine-containing CNS drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Meptazinol, a phenolic tertiary amine with very low F (8.7 ± 1.6%), is contradictory evidence that phenolic/basic-amine structures can undergo extensive first-pass metabolism and fall below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pentazocine, a close benzomorphan opioid with a phenolic OH and N-methyl, has mean oral bioavailability ~18%, contradictory evidence that this opioid class can be borderline below 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 4,5-epoxymorphinan opioid with a phenolic 3-OH, N-methylamine, and 6-ketone. The closest morphinan analogue, codeine, has 80.5% oral bioavailability, and multiple high-transfer analogues with phenolic, basic-amine, or opioid features show F ≥ 50%. Although meptazinol and pentazocine demonstrate that some phenolic/basic-amine opioids can undergo extensive first-pass metabolism and fall below 20%, the preponderance of structurally relevant evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the supplied evidence.",
    "First-pass conjugation and hepatic metabolism of phenolic morphinans is variable; codeine's high F may not fully capture the effect of the 6-ketone in the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

